from game import Game

def main():
    game = Game()
    while True:
        game.print_board()
        move = input(f"Player {game.current_player}, enter your move (from-to): ")
        if move.lower() == 'quit':
            break
        try:
            from_pos = tuple(map(int, move.split('-')[0].split()))
            to_pos = tuple(map(int, move.split('-')[1].split()))
            game.make_move(from_pos, to_pos)
        except (ValueError, IndexError):
            print("Invalid input. Please enter moves in the format 'row-col-row-col'.")

        winner = game.check_winner()
        if winner:
            game.print_board()
            print(f"Player {winner} wins!")
