import tkinter as tk
from game import Game
class CheckersGUI:
    def __init__(self, root):
        self.root = root
        self.root.title("Checkers Game")
        self.game = Game()
        self.board_frame = tk.Frame(self.root)
        self.board_frame.pack()
        self.buttons = [[None for _ in range(8)] for _ in range(8)]
        for row in range(8):
            for col in range(8):
                button = tk.Button(self.board_frame, text="", width=5, height=2, command=lambda r=row, c=col: self.on_button_click(r, c))
                button.grid(row=row, column=col)
                self.buttons[row][col] = button
        self.update_board()
    def update_board(self):
        for row in range(8):
            for col in range(8):
                piece = self.game.board.board[row][col]
                if piece:
                    self.buttons[row][col].config(text=str(piece))
                else:
                    self.buttons[row][col].config(text="")
    def on_button_click(self, row, col):
        if self.game.current_player == 'W':
            self.game.make_move((row, col), (row, col))
            self.update_board()
